function read(name) {
  return fs.readFileSync(path.join(root, name), "utf8");
}

function loadTracks(file) {
  const ctx = { window: {} };
  vm.createContext(ctx);
  vm.runInContext(read(file), ctx);
  return ctx.window.VOCAB_EXAM_TRACKS;
}

