  const placed = withIpa({ word: "able", pos: "adj.", related: ["be able to"] }, "/ˈeɪbəl/");
  assert.deepStrictEqual(Object.keys(placed), ["word", "pos", "ipa", "related"]);
  assert.strictEqual(placed.related[0], "be able to");
