function cardsOf(track) {
  const out = [];
  for (const set of track.sets) for (const card of set) out.push(card);
  return out;
}

{
  for (const track of [zk, gk]) {
    for (const card of cardsOf(track)) {
      const ipa = ipaFor(card.word, card.pos || "", map);
      assert.strictEqual(card.ipa, ipa, track.id + " " + card.word);
      assert.ok(/^\/.+\/$/.test(card.ipa), card.word + " " + card.ipa);
      assert.ok(!card.ipa.includes("ɹ"), card.word);
    }
  }
  assert.strictEqual(zk.sets.slice(0, 58).flat().length, 2821);
  assert.strictEqual(zk.sets.slice(58).flat().length, 515);
  assert.strictEqual(gk.sets.slice(0, 86).flat().length, 4243);
  assert.strictEqual(gk.sets.slice(86).flat().length, 517);
  const able = zk.sets.flat().find((c) => c.word === "able");
  assert.strictEqual(able.meaning_zh, "能够；有能力的");
  assert.strictEqual(able.ipa, "/ˈeɪbəl/");
  const phrase = zk.sets.flat().find((c) => c.word === "be able to");
  assert.ok(phrase.ipa.startsWith("/"));
  assert.ok(phrase.example_en.includes("able"));

  const zkBuilt = buildZhongkao(zk.sets.slice(0, 58).flat().map((c) => c.word));
  assert.strictEqual(zkBuilt.length, 515);
  assert.ok(zkBuilt.every((c) => c.ipa && c.ipa === ipaFor(c.word, c.pos, map)));
  const gkBuilt = buildGaokao(gk.sets.slice(0, 86).flat().map((c) => c.word));
  assert.strictEqual(gkBuilt.length, 517);
  assert.ok(gkBuilt.every((c) => c.ipa && c.ipa === ipaFor(c.word, c.pos, map)));
  assert.strictEqual(rootTracks.find((t) => t.id === "zhongkao").sets.flat().length, 2821);
}

function contentType(file) {
  switch (path.extname(file)) {
    case ".html": return "text/html; charset=utf-8";
    case ".js": return "text/javascript; charset=utf-8";
    case ".svg": return "image/svg+xml";
    case ".png": return "image/png";
    case ".webmanifest": return "application/manifest+json";
    default: return "application/octet-stream";
  }
}

function startServer() {
  return new Promise((resolve) => {
    const server = http.createServer((req, res) => {
      const urlPath = decodeURIComponent((req.url || "/").split("?")[0]);
      const rel = urlPath === "/" ? "index.html" : urlPath.replace(/^\/+/, "");
      const file = path.normalize(path.join(root, rel));
      if (!file.startsWith(root)) {
        res.writeHead(403);
        res.end();
        return;
      }
      fs.readFile(file, (err, buf) => {
        if (err) {
          res.writeHead(404);
          res.end("missing");
          return;
        }
        res.writeHead(200, { "content-type": contentType(file) });
        res.end(buf);
      });
    });
    server.listen(0, "127.0.0.1", () => resolve(server));
  });
}

