function plant(trackId, focusWord) {
  const sense = require("../grok/sense-id");
  const track = grok.find((t) => t.id === trackId);
  const future = Date.now() + 10 * 86400000;
  const cards = {};
  for (const w of track.sets[0]) {
    if (w.word === focusWord) continue;
    cards[sense.cardKeyFor(trackId, 0, w.word)] = {
      ef: 2.5, interval: 3, reps: 4, lapses: 0, due: future,
      correct: 4, wrong: 0, unknown: 0, mastery: 3, mastered: true,
      state: "review", scheduledAt: future,
    };
  }
  return {
    points: 4, streak: 0, bestStreak: 1, unlockedLevel: 1, cards,
    levelStars: {}, sortMode: "default", voiceOn: false, track: trackId,
    trackUnlock: { [trackId]: 1 }, trackStars: { [trackId]: {} }, daily: {},
    profile: { name: "小王", cls: "初三1班" },
    practice: { meaning: { n: 0, good: 0 }, spelling: { n: 0, good: 0 }, hint: { n: 0, good: 0 } },
    updatedAt: "2026-10-30T00:00:00.000Z",
  };
}

function earlyScript(save) {
  return `(function () {
    if(location.pathname.indexOf('/grok/index.html')===-1)return;
    try { localStorage.setItem("quizmario-auth", ${JSON.stringify(JSON.stringify(SESSION))}); } catch (e) {}
    try { sessionStorage.setItem("qm-phase", "signed"); } catch (e) {}
    // Each planted teaching scenario is a fresh server/cache fixture. Recovery
    // journals from the preceding scenario are tested separately by the sync suite.
    try { for(var i=localStorage.length-1;i>=0;i--){var k=localStorage.key(i);if(k.indexOf('quizmario-progress-pending-v2:account:'+${JSON.stringify(SESSION.user.id)}+':')===0||k.indexOf('quizmario-event-pending-v2:'+${JSON.stringify(SESSION.user.id)}+':')===0)localStorage.removeItem(k);} } catch(e) {}

    try { localStorage.setItem("vocabSpotlight_v1:account:"+${JSON.stringify(SESSION.user.id)}, ${JSON.stringify(JSON.stringify(save))}); } catch (e) {}
    window.__QM_MOCK_PROGRESS=${JSON.stringify(save)};
    if (window.__QM_SMOKE_FETCH) return;
    var cloudVersion = "2026-01-01T00:00:00.000Z", cloudRevision = 0;
    window.__QM_SMOKE_FETCH = [];

    var orig = window.fetch ? window.fetch.bind(window) : null;
    function reply(status, payload) {
      return Promise.resolve(new Response(JSON.stringify(payload), {
        status: status,
        headers: { "content-type": "application/json" },
      }));
    }
    window.fetch = function (input, init) {
      var url = typeof input === "string" ? input : (input && input.url) || "";
      var method = ((init && init.method) || (input && input.method) || "GET").toUpperCase();
      if (!/supabase\\.co/i.test(url)) {
        if (!orig) return Promise.reject(new Error("no fetch"));
        return orig(input, init);
      }
      if (url.indexOf("/user_progress") !== -1) {
        if (method === "GET" || method === "HEAD") return reply(200, window.__QM_MOCK_PROGRESS ? [{save:window.__QM_MOCK_PROGRESS,updated_at:cloudVersion}] : []);
        var expected = new URL(url).searchParams.get("updated_at");
        if (method === "PATCH" && expected && expected !== "eq."+cloudVersion) return reply(406, {code:"PGRST116",details:"The result contains 0 rows",message:"JSON object requested"});
        var body = JSON.parse(init.body || "{}"); if(Array.isArray(body))body=body[0]; window.__QM_MOCK_PROGRESS = body.save;
        cloudVersion = new Date(Date.now()+(++cloudRevision)).toISOString();
        return reply(200, {user_id:${JSON.stringify(SESSION.user.id)},save:window.__QM_MOCK_PROGRESS,updated_at:cloudVersion});
      }
      if (url.indexOf("/learner_events") !== -1) return reply(200, []);
      if (url.indexOf("/auth/v1/user") !== -1) return reply(200, ${JSON.stringify(SESSION.user)});
      if (url.indexOf("/token") !== -1 || url.indexOf("/signup") !== -1) return reply(200, ${JSON.stringify(SESSION)});
      return reply(200, {});
    };
  })();`;
}

class Cdp {
  constructor(ws) {
    this.ws = ws;
    this.next = 0;
    this.pending = new Map();
    ws.addEventListener("message", (ev) => {
      const msg = JSON.parse(ev.data);
      if (msg.id && this.pending.has(msg.id)) {
        const job = this.pending.get(msg.id);
        this.pending.delete(msg.id);
        if (msg.error) job.reject(new Error(msg.error.message || JSON.stringify(msg.error)));
        else job.resolve(msg.result || {});
      }
    });
  }
  send(method, params, sessionId) {
    const id = ++this.next;
    const payload = { id, method, params: params || {} };
    if (sessionId) payload.sessionId = sessionId;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      this.ws.send(JSON.stringify(payload));
    });
  }
}

function launchChrome(userDir) {
  const chrome = spawn("google-chrome", [
    "--headless=new", "--no-sandbox", "--disable-gpu", "--disable-dev-shm-usage",
    "--mute-audio", "--no-first-run", "--remote-debugging-port=0", "--remote-allow-origins=*",
    `--user-data-dir=${userDir}`, "about:blank",
  ], { stdio: ["ignore", "pipe", "pipe"] });
  const port = new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error("Chrome did not open a DevTools port")), 20000);
    let buf = "";
    const onData = (chunk) => {
      buf += chunk.toString();
      const match = buf.match(/DevTools listening on ws:\/\/127\.0\.0\.1:(\d+)\//);
      if (match) {
        clearTimeout(timer);
        resolve(Number(match[1]));
      }
    };
    chrome.stderr.on("data", onData);
    chrome.stdout.on("data", onData);
    chrome.on("exit", (code) => {
      clearTimeout(timer);
      reject(new Error("Chrome exited early (" + code + ")"));
    });
  });
  return { chrome, port };
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function browserSmoke() {
  const server = await startServer();
  const origin = "http://127.0.0.1:" + server.address().port;
  const userDir = fs.mkdtempSync(path.join(os.tmpdir(), "qm-ipa-"));
  const launched = launchChrome(userDir);
  const shots = [];
  try {
    const port = await launched.port;
    const version = await (await fetch("http://127.0.0.1:" + port + "/json/version")).json();
    const ws = new WebSocket(version.webSocketDebuggerUrl);
    await new Promise((resolve, reject) => {
      ws.addEventListener("open", resolve);
      ws.addEventListener("error", () => reject(new Error("DevTools websocket failed")));
    });
    const cdp = new Cdp(ws);
    const created = await cdp.send("Target.createTarget", { url: "about:blank" });
    const attached = await cdp.send("Target.attachToTarget", { targetId: created.targetId, flatten: true });
    const sessionId = attached.sessionId;
    await cdp.send("Page.enable", {}, sessionId);
    await cdp.send("Runtime.enable", {}, sessionId);
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width: 420, height: 900, deviceScaleFactor: 1, mobile: true,
    }, sessionId);

    const evaluate = async (expression) => {
      const res = await cdp.send("Runtime.evaluate", {
        expression, awaitPromise: true, returnByValue: true,
      }, sessionId);
      if (res.exceptionDetails) {
        const desc = res.exceptionDetails.exception && res.exceptionDetails.exception.description;
        throw new Error(res.exceptionDetails.text + (desc ? " " + desc : ""));
      }
      return res.result ? res.result.value : undefined;
    };
    const waitFor = async (fn, ms, label) => {
      const start = Date.now();
      let last = null;
      while (Date.now() - start < ms) {
        last = await fn();
        if (last) return last;
        await sleep(80);
      }
      throw new Error("timed out waiting for " + label + " last=" + JSON.stringify(last));
    };
    const shot = async (name) => {
      const dir = path.join(require("os").tmpdir(), "quizmario-test-artifacts", path.basename(__filename), "screenshots");
      fs.mkdirSync(dir, { recursive: true });
      const png = await cdp.send("Page.captureScreenshot", { format: "png" }, sessionId);
      const file = path.join(dir, name + ".png");
      fs.writeFileSync(file, Buffer.from(png.data, "base64"));
      shots.push(file);
      return file;
    };
    const dismissHome = async () => waitFor(async () => evaluate(`(() => {
      const prompt = document.getElementById("profile-name-gate");
      if (prompt && !prompt.hidden) {
        document.getElementById("profile-name-input").value = "小王";
        document.getElementById("profile-class-input").value = "初三1班";
        document.getElementById("profile-name-form").requestSubmit();
      }
      const soft = document.getElementById("must-gate");
      if (soft && !soft.hidden) {
        const later = document.getElementById("btn-must-later");
        if (later) later.click();
      }
      const home = document.getElementById("screen-home");
      if (!home || !home.classList.contains("active")) return null;
      if (soft && !soft.hidden) return null;
      return true;
    })()`), 20000, "home");

    async function openTrack(trackId, buttonId, save) {
      const added = await cdp.send("Page.addScriptToEvaluateOnNewDocument", { source: earlyScript(save) }, sessionId);
      await cdp.send("Page.navigate", { url: origin + "/grok/index.html" }, sessionId);
      await waitFor(async () => evaluate(`(() => {
        const btn = document.getElementById(${JSON.stringify(buttonId)});
        const gate = document.getElementById("screen-gate");
        if (!btn || !gate || !gate.classList.contains("active")) return null;
        if (!document.documentElement.classList.contains("session-ok")) return null;
        return true;
      })()`), 20000, "gate " + trackId);
      await evaluate(`document.getElementById(${JSON.stringify(buttonId)}).click()`);
      await dismissHome();
      await cdp.send("Page.removeScriptToEvaluateOnNewDocument", { identifier: added.identifier }, sessionId);
    }

    const readPrompt = () => evaluate(`(() => {
      const main = document.getElementById("prompt-main");
      const ipa = document.getElementById("prompt-ipa");
      const say = document.querySelector('#card-speak .speak-btn[data-say-kind="word"]:not([data-say-slow="1"])');
      const play = document.getElementById("screen-play");
      return {
        play: !!(play && play.classList.contains("active")),
        word: main ? main.textContent : "",
        ipa: ipa && !ipa.hidden ? ipa.textContent : "",
        ipaInsidePrompt: main ? main.textContent : "",
        say: say ? say.getAttribute("data-say") : "",
        level: (document.getElementById("play-level") || {}).textContent || "",
        gate: (document.getElementById("prompt-box") || {}).getAttribute("data-colloc-gate") || "",
      };
    })()`);

    const able = zk.sets.flat().find((c) => c.word === "able");
    const phrase = zk.sets.flat().find((c) => c.word === "be able to");
    await openTrack("zhongkao", "btn-gate-zhongkao", plant("zhongkao", "able"));
    await evaluate(`document.getElementById("btn-continue").click()`);
    const first = await waitFor(async () => {
      const snap = await readPrompt();
      if (!snap || !snap.play || snap.word !== "able" || !snap.ipa) return null;
      return snap;
    }, 15000, "中考 able");
    assert.strictEqual(first.word, "able");
    assert.strictEqual(first.ipa, able.ipa);
    assert.ok(!first.word.includes("/"), "IPA stays out of the prompt text");
    assert.strictEqual(first.say, "able", "TTS button speaks the spelling");
    await shot("zhongkao-ordinary-ipa");

    await evaluate(`(() => {
      const chip = document.querySelector('#card-related .related-chip');
      if (!chip) return false;
      chip.click();
      return true;
    })()`);
    const peek = await waitFor(async () => evaluate(`(() => {
      const box = document.getElementById("related-peek");
      if (!box || box.hidden) return null;
      return {
        word: (document.getElementById("related-peek-word") || {}).textContent || "",
        ipa: (document.getElementById("related-peek-ipa") || {}).textContent || "",
      };
    })()`), 8000, "related peek");
    assert.strictEqual(peek.word, "be able to");
    assert.strictEqual(peek.ipa, phrase.ipa);
    await shot("zhongkao-related-ipa");
    await evaluate(`document.getElementById("related-peek-close").click()`);

    const clicked = await evaluate(`(() => {
      const want = ${JSON.stringify(able.meaning_zh)};
      const btn = [...document.querySelectorAll("#choices .choice")].find((el) => el.textContent.indexOf(want) !== -1);
      if (!btn) return "";
      btn.click();
      return btn.textContent;
    })()`);
    assert.ok(clicked, "could not click the 中考 meaning");
    const gate = await waitFor(async () => {
      const snap = await readPrompt();
      if (!snap || snap.gate !== "be able to" || snap.word !== "be able to") return null;
      return snap;
    }, 8000, "colloc gate ipa");
    assert.strictEqual(gate.ipa, phrase.ipa);
    assert.strictEqual(gate.word, "be able to");
    await shot("zhongkao-colloc-gate-ipa");

    await evaluate(`document.getElementById("btn-quit").click()`);
    await dismissHome();
    await evaluate(`document.getElementById("btn-levels").click()`);
    const opened = await waitFor(async () => evaluate(`(() => {
      const grid = document.getElementById("level-grid");
      if (!grid || !grid.children.length) return "";
      const card = [...grid.querySelectorAll(".level-card")].find((el) => el.textContent.indexOf("固定搭配") !== -1 && !el.classList.contains("locked"));
      if (!card) return "";
      const title = (card.querySelector(".ln") || {}).textContent || "";
      card.querySelector(".ln").click();
      return title;
    })()`), 8000, "固定搭配 set");
    assert.ok(opened.includes("固定搭配"), opened);
    const colloc = await waitFor(async () => {
      const snap = await readPrompt();
      if (!snap || !snap.play || !snap.level.includes("固定搭配") || !snap.ipa) return null;
      return snap;
    }, 8000, "固定搭配 card");
    const collocCard = zk.sets.flat().find((c) => c.word === colloc.word);
    assert.ok(collocCard, colloc.word);
    assert.strictEqual(colloc.ipa, collocCard.ipa);
    assert.strictEqual(colloc.say, colloc.word);
    await shot("zhongkao-colloc-set-ipa");

    const gkCard = gk.sets[0].find((c) => c.word === "ability") || gk.sets[0].find((c) => c.word.length > 3);
    await openTrack("gaokao", "btn-gate-gaokao", plant("gaokao", gkCard.word));
    await evaluate(`document.getElementById("btn-continue").click()`);
    const senior = await waitFor(async () => {
      const snap = await readPrompt();
      if (!snap || snap.word !== gkCard.word || !snap.ipa) return null;
      return snap;
    }, 15000, "高考 card");
    assert.strictEqual(senior.ipa, gkCard.ipa);
    assert.strictEqual(senior.say, gkCard.word);
    assert.ok(!senior.word.includes("/"));
    await shot("gaokao-ordinary-ipa");
    return shots;
  } finally {
    if (launched.chrome && !launched.chrome.killed) launched.chrome.kill("SIGKILL");
    server.close();
  }
}

async function main() {
  const shots = await browserSmoke();
  console.log("ipa-cards ok");
  console.log(shots.join("\n"));
}

main().catch((err) => {
  console.error(err && err.stack ? err.stack : err);
  process.exit(1);
});
